v:
{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique como a forma das células animais e vegetais pode influenciar suas funções.",
      "resposta_esperada": "A forma irregular das células animais permite maior flexibilidade e adaptação a diferentes ambientes, enquanto a forma fixa das células vegetais proporciona estabilidade e suporte estrutural."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva uma situação em que a presença da parede celular nas células vegetais é vantajosa para a planta.",
      "resposta_esperada": "A parede celular ajuda a planta a resistir à pressão interna causada pela entrada de água, evitando a ruptura das células e permitindo que a planta mantenha sua forma e estrutura."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as estruturas da membrana plasmática e da parede celular, destacando suas funções e diferenças.",
      "resposta_esperada": "A membrana plasmática controla a entrada e saída de substâncias, enquanto a parede celular, composta principalmente por celulose, oferece proteção e suporte, sendo uma estrutura exclusiva das células vegetais."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Descreva a função da membrana plasmática na célula.",
      "resposta_esperada": "A membrana plasmática é o envoltório externo da célula que regula a troca de substâncias entre a célula e o meio externo, protegendo-a e mantendo seu ambiente interno."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Explique como o citoplasma contribui para o funcionamento celular.",
      "resposta_esperada": "O citoplasma, sendo um material gelatinoso, permite que as organelas fiquem suspensas e facilita as reações químicas, como a transformação de nutrientes que entram na célula."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as funções do núcleo e da membrana plasmática em uma célula.",
      "resposta_esperada": "Enquanto a membrana plasmática regula a troca de substâncias e protege a célula, o núcleo coordena as funções celulares e contém o DNA, essencial para a multiplicação celular e a hereditariedade."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Quais são as principais funções do tecido epitelial no corpo humano?",
      "resposta_esperada": "O tecido epitelial tem a função de revestir superfícies do corpo, proteger os órgãos internos e participar da absorção e secreção de substâncias."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Como a falta de vascularização do tecido epitelial pode impactar sua capacidade de renovação celular?",
      "resposta_esperada": "A falta de vascularização significa que o tecido epitelial depende da difusão de nutrientes e oxigênio de tecidos adjacentes, o que pode limitar sua capacidade de renovação em comparação com tecidos vascularizados."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as características do tecido epitelial com as de outros tipos de tecido, como o tecido conjuntivo. Quais são as principais diferenças?",
      "resposta_esperada": "Enquanto o tecido epitelial apresenta células justapostas e pouca substância intercelular, o tecido conjuntivo possui mais substância intercelular e células mais espaçadas, além de ser vascularizado, permitindo maior suporte e nutrição."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique o que é metabolismo celular e sua importância para as células.",
      "resposta_esperada": "O metabolismo celular é o conjunto de reações químicas que ocorrem dentro das células. Ele é importante porque fornece a energia necessária para que as células realizem suas funções vitais."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de como o metabolismo celular pode ser afetado por uma dieta inadequada.",
      "resposta_esperada": "Uma dieta inadequada pode levar à falta de nutrientes essenciais, o que pode prejudicar o metabolismo celular, resultando em menor produção de energia e comprometendo o funcionamento das células."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as fases anabólicas e catabólicas do metabolismo celular e discorra sobre suas funções.",
      "resposta_esperada": "As fases anabólicas do metabolismo celular são responsáveis pela síntese de moléculas complexas a partir de moléculas simples, enquanto as fases catabólicas quebram moléculas complexas em moléculas mais simples, liberando energia. Ambas são essenciais para o equilíbrio e funcionamento adequado das células."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique o que se entende por fenótipo e como ele pode ser influenciado pelo ambiente.",
      "resposta_esperada": "O fenótipo é o conjunto de características observáveis de um organismo, como cor dos olhos ou altura. Ele pode ser influenciado por fatores ambientais, como dieta e clima."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de como o genótipo de um indivíduo pode determinar seu fenótipo em uma característica específica.",
      "resposta_esperada": "Por exemplo, um indivíduo com um genótipo que determina a cor dos olhos pode ter olhos azuis, o que é uma expressão do seu fenótipo, independentemente de outros fatores."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare e contraste o impacto do genótipo e do fenótipo na hereditariedade de características em uma população.",
      "resposta_esperada": "O genótipo é a base genética que é herdada dos pais e define as potencialidades de um organismo, enquanto o fenótipo é a expressão dessas características que pode ser alterada por fatores ambientais, mostrando que ambos são importantes na hereditariedade, mas atuam de maneiras diferentes."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique o que são características hereditárias e como elas se relacionam com a genética.",
      "resposta_esperada": "Características hereditárias são traços que podem ser transmitidos de pais para filhos através dos genes, que são as unidades básicas da hereditariedade na genética."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de uma característica hereditária e descreva como ela pode ser transmitida de uma geração para outra.",
      "resposta_esperada": "Um exemplo de característica hereditária é a cor dos olhos. Se um dos pais tem olhos azuis e o outro tem olhos castanhos, os filhos podem herdar a cor dos olhos de um dos pais, dependendo dos genes que recebem."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a transmissão de características hereditárias em organismos diferentes, como plantas e animais, e discorra sobre as semelhanças e diferenças.",
      "resposta_esperada": "Tanto em plantas quanto em animais, a transmissão de características hereditárias ocorre através de genes, mas as formas de herança podem variar. Por exemplo, em plantas, a polinização pode influenciar a herança, enquanto em animais, a reprodução sexual desempenha um papel crucial na combinação de genes."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Quais são as principais funções dos órgãos sexuais internos do homem na reprodução?",
      "resposta_esperada": "Os órgãos sexuais internos do homem têm a função de produzir, nutrir e transportar os espermatozoides, essenciais para a reprodução."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva como os espermatozoides são transportados desde a produção até a ejaculação.",
      "resposta_esperada": "Os espermatozoides são produzidos nos testículos, maturam no epidídimo, são transportados pelo ducto deferente e, ao se misturarem com os fluidos das glândulas anexas, chegam à uretra para serem ejaculado."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as funções da próstata e da vesícula seminal no processo de reprodução masculina.",
      "resposta_esperada": "A próstata produz um líquido que nutre os espermatozoides e facilita sua mobilidade, enquanto a vesícula seminal secreta um fluido que fornece energia e ajuda na formação do sêmen, ambos essenciais para a fecundação."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Descreva o que acontece com o diafragma durante a inspiração e a expiração.",
      "resposta_esperada": "Durante a inspiração, o diafragma se contrai e se move para baixo, aumentando o volume da cavidade torácica. Na expiração, o diafragma relaxa e se eleva, ajudando a expulsar o ar dos pulmões."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Explique como a atividade física pode influenciar o processo de respiração, considerando o papel dos músculos intercostais.",
      "resposta_esperada": "Durante a atividade física, os músculos intercostais se contraem mais intensamente para facilitar a entrada de ar nos pulmões, aumentando a capacidade respiratória e a oxigenação do sangue."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare os processos de inspiração e expiração, destacando as diferenças nos movimentos musculares envolvidos.",
      "resposta_esperada": "Na inspiração, ocorre a contração do diafragma e dos músculos intercostais, que elevam a caixa torácica e permitem a entrada de ar. Já na expiração, os músculos intercostais e o diafragma relaxam, reduzindo o volume da cavidade torácica e expulsando o ar."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique como o aumento da concentração de gás carbônico no sangue está relacionado ao controle da respiração pelo sistema nervoso.",
      "resposta_esperada": "O aumento da concentração de gás carbônico no sangue é detectado pelo sistema nervoso, que ativa o bulbo raquidiano para reiniciar a respiração, garantindo que o organismo mantenha níveis adequados de oxigênio."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Imagine que uma pessoa está praticando exercícios físicos intensos. Como o corpo dela reage em relação à respiração e ao gás carbônico durante essa atividade?",
      "resposta_esperada": "Durante exercícios intensos, o corpo produz mais gás carbônico, o que leva o sistema nervoso a aumentar a frequência respiratória para eliminar o excesso de gás carbônico e fornecer mais oxigênio aos músculos."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a respiração voluntária e involuntária, destacando o papel do bulbo raquidiano em cada uma delas.",
      "resposta_esperada": "A respiração voluntária é controlada conscientemente, permitindo que a pessoa suspenda a respiração temporariamente, enquanto a respiração involuntária é regulada pelo bulbo raquidiano, que automaticamente responde ao aumento de gás carbônico no sangue, forçando a respiração para proteger o organismo."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique a importância do núcleo nas células para o estudo dos cromossomos.",
      "resposta_esperada": "O núcleo é importante porque é onde os cromossomos estão localizados. Sem o núcleo, não é possível estudar os cromossomos, pois eles não estariam presentes na célula."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Se você tivesse que coletar células para um exame genético, qual tipo de célula sanguínea você escolheria e por quê?",
      "resposta_esperada": "Eu escolheria os leucócitos, pois eles contêm núcleo e, portanto, possuem cromossomos, que são necessários para o exame genético."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as hemácias e os leucócitos em relação à presença de núcleo e à sua função no organismo.",
      "resposta_esperada": "As hemácias não possuem núcleo e são responsáveis pelo transporte de oxigênio, enquanto os leucócitos têm núcleo e atuam na defesa do organismo contra infecções. Essa diferença é crucial para suas respectivas funções."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique a função das artérias no sistema circulatório.",
      "resposta_esperada": "As artérias são responsáveis por transportar o sangue do coração para os tecidos do corpo, levando oxigênio e nutrientes essenciais."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva como o sangue rico em oxigênio é distribuído pelo corpo e como ele retorna ao coração.",
      "resposta_esperada": "O sangue rico em oxigênio é bombeado do coração para as artérias, que se ramificam e levam o sangue aos tecidos; depois, o sangue, agora pobre em oxigênio e rico em gás carbônico, retorna ao coração pelas veias."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare o papel das veias e artérias na remoção de toxinas do corpo.",
      "resposta_esperada": "Enquanto as artérias transportam sangue rico em oxigênio para os tecidos, as veias são responsáveis por levar o sangue de volta ao coração, removendo as toxinas acumuladas nos tecidos durante esse processo."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique qual é o papel do fígado na metabolização de nutrientes durante a digestão.",
      "resposta_esperada": "O fígado desempenha um papel crucial na metabolização de nutrientes, armazenando-os e transformando-os em formas que podem ser absorvidas e utilizadas pelo organismo."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva como a produção de bile pelo fígado pode afetar a digestão de gorduras.",
      "resposta_esperada": "A bile produzida pelo fígado emulsifica as gorduras, facilitando sua digestão e absorção no intestino delgado."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare as funções do fígado na digestão com as de outro órgão do sistema digestório, como o pâncreas.",
      "resposta_esperada": "Enquanto o fígado é responsável pela produção de bile e metabolização de nutrientes, o pâncreas secreta enzimas digestivas que ajudam na quebra de carboidratos, proteínas e gorduras, mostrando que ambos os órgãos têm funções complementares na digestão."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique o que acontece com o sistema imunológico quando uma vacina é administrada ao corpo humano.",
      "resposta_esperada": "Quando uma vacina é administrada, o sistema imunológico reage produzindo anticorpos para combater a substância introduzida, promovendo a imunização."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva uma situação em que a vacinação pode ser crucial para a saúde pública, mencionando como ela atua no corpo.",
      "resposta_esperada": "Durante um surto de uma doença contagiosa, a vacinação é crucial, pois ela estimula o corpo a produzir anticorpos, ajudando a imunizar a população e a prevenir a propagação da doença."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a resposta do corpo a uma infecção natural com a resposta a uma vacina, focando na produção de anticorpos.",
      "resposta_esperada": "A infecção natural provoca uma resposta imunológica que pode ser mais intensa e prolongada, enquanto a vacina induz a produção de anticorpos de forma controlada e segura, preparando o corpo para uma possível infecção futura sem causar a doença."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique a importância de incluir alimentos de diferentes grupos na sua dieta diária.",
      "resposta_esperada": "Incluir alimentos de diferentes grupos na dieta é importante porque cada grupo desempenha funções específicas, como fornecer energia, promover o crescimento e regular processos no corpo."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de como você poderia montar um prato saudável que inclui alimentos de todos os grupos nutricionais.",
      "resposta_esperada": "Um exemplo de prato saudável seria um prato com arroz (energético), frango grelhado (construtor) e uma salada de folhas verdes e legumes (reguladores), garantindo uma refeição equilibrada."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare os efeitos de uma dieta que inclui apenas alimentos energéticos com uma dieta equilibrada que contém todos os grupos alimentares.",
      "resposta_esperada": "Uma dieta que inclui apenas alimentos energéticos pode levar a problemas de saúde, como obesidade e falta de nutrientes, enquanto uma dieta equilibrada promove um melhor funcionamento do corpo e previne doenças."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique a função dos rins no corpo humano e como a hemodiálise se relaciona a essa função.",
      "resposta_esperada": "Os rins são responsáveis por filtrar o sangue, removendo toxinas e excesso de água. A hemodiálise substitui essa função quando os rins não conseguem mais fazê-lo."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva uma situação em que a hemodiálise seria necessária e como ela ajudaria o paciente.",
      "resposta_esperada": "A hemodiálise seria necessária em um paciente com insuficiência renal, onde a máquina filtraria o sangue para remover toxinas e excesso de líquidos, ajudando a manter a saúde do paciente."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare os efeitos da hemodiálise e do funcionamento normal dos rins no equilíbrio de substâncias no corpo.",
      "resposta_esperada": "Enquanto os rins regulam naturalmente o equilíbrio de substâncias e fluidos no corpo, a hemodiálise realiza essa função de forma artificial, removendo toxinas e água, mas não consegue replicar completamente a complexidade do funcionamento renal normal."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique por que a presença da parede celular é importante para as células vegetais.",
      "resposta_esperada": "A parede celular é importante para as células vegetais porque fornece suporte e resistência, ajudando a manter a forma da célula e evitando que ela se rompa quando há muita água."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Dê um exemplo de como a forma irregular das células animais pode ser vantajosa em comparação com a forma fixa das células vegetais.",
      "resposta_esperada": "A forma irregular das células animais permite que elas se acomodem melhor em diferentes tecidos e órgãos, facilitando a formação de estruturas complexas, como músculos e nervos."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a composição da parede celular das células vegetais com a estrutura das células animais. Quais implicações isso pode ter para a função dessas células?",
      "resposta_esperada": "A parede celular das células vegetais é composta principalmente de celulose, o que proporciona rigidez e proteção, enquanto as células animais não possuem essa estrutura, permitindo maior flexibilidade e variedade de formas, o que é crucial para suas funções especializadas."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Descreva como é o formato das células animais em comparação com as células vegetais.",
      "resposta_esperada": "As células animais possuem um formato irregular, enquanto as células vegetais têm uma forma fixa, geralmente retangular ou quadrada."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Explique por que a parede celular é importante para as células vegetais, utilizando um exemplo do dia a dia.",
      "resposta_esperada": "A parede celular é importante porque dá suporte e proteção às células vegetais, evitando que se rompam quando absorvem água, assim como a parede de uma casa mantém a estrutura firme."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a composição da parede celular das células vegetais com a estrutura das células animais e discorra sobre as implicações dessa diferença.",
      "resposta_esperada": "A parede celular das células vegetais é composta principalmente de celulose, o que proporciona resistência, enquanto as células animais não possuem parede celular, o que as torna mais flexíveis, mas também mais suscetíveis a rupturas."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique como o formato das células animais e vegetais contribui para suas funções.",
      "resposta_esperada": "O formato irregular das células animais permite flexibilidade e adaptação a diferentes ambientes, enquanto o formato fixo e retangular das células vegetais proporciona estrutura e suporte, essencial para a manutenção da planta."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Imagine que você está observando uma célula vegetal ao microscópio. Como você identificaria a presença da parede celular e qual seria sua importância?",
      "resposta_esperada": "Eu identificaria a parede celular pela sua estrutura rígida que envolve a célula. Sua importância está em fornecer resistência, evitando a ruptura da célula quando ela absorve água."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a função da membrana plasmática nas células animais e vegetais e discorra sobre como essa função é influenciada pela presença da parede celular nas células vegetais.",
      "resposta_esperada": "A membrana plasmática controla a entrada e saída de substâncias em ambas as células, mas nas células vegetais, a presença da parede celular complementa essa função, oferecendo proteção e estrutura, permitindo que a célula mantenha sua forma mesmo sob pressão interna."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Explique como o formato das células animais e vegetais se relaciona com suas funções.",
      "resposta_esperada": "As células animais têm um formato irregular que permite flexibilidade e adaptação, enquanto as células vegetais têm um formato fixo que proporciona suporte e resistência."
    },
    {
      "nivel_bloom": "aplicar",
      "enunciado": "Descreva uma situação em que a presença da parede celular nas células vegetais é vantajosa.",
      "resposta_esperada": "A parede celular é vantajosa quando as células vegetais absorvem água, pois evita que elas se rompam devido à pressão interna."
    },
    {
      "nivel_bloom": "analisar",
      "enunciado": "Compare a composição das células animais e vegetais em relação à parede celular e discorra sobre as implicações dessa diferença.",
      "resposta_esperada": "Enquanto as células vegetais possuem uma parede celular composta principalmente de celulose, as células animais não têm essa estrutura, o que implica que as células vegetais são mais resistentes à pressão interna, enquanto as células animais são mais flexíveis."
    }
  ]
}

{
  "questoes": [
    {
      "nivel_bloom": "entender",
      "enunciado": "Descreva como é o formato das células animais e vegetais, destacando as diferenças entre elas.",
      "resposta_esperada": "As células animais possuem um formato irregular, enquanto as células vegetais têm uma forma fixa e definida, como um retângulo ou quadrado."
    },
